from pathlib import Path

def replace_once(text, old, new, label):
    if text.count(old) != 1:
        raise SystemExit(f'{label}: expected exactly one replacement, found {text.count(old)}')
    return text.replace(old, new, 1)

def strip_final_step(text, marker, label):
    if text.count(marker) != 1:
        raise SystemExit(f'{label}: expected one final-step marker, found {text.count(marker)}')
    return text.split(marker, 1)[0].rstrip() + '\n'

